:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --btn-bg: #0f3460;
  --btn-hover: #1a4a7a;
  --btn-active: #0a2540;
  --focus: #f5c542;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 3px solid var(--accent);
  border-radius: 12px;
  padding: 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.4rem;
  margin-bottom: 16px;
  color: var(--accent);
  letter-spacing: 1px;
}

.meter {
  margin: 0 auto 16px;
  width: 160px;
  height: 120px;
  image-rendering: pixelated;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.display {
  background: #0a0a1a;
  border: 2px solid var(--accent);
  border-radius: 8px;
  padding: 12px;
  margin-bottom: 20px;
}

.time, .price {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 4px 0;
}

.label {
  color: var(--muted);
  font-size: 0.9rem;
}

#timeDisplay, #priceDisplay {
  font-family: 'Courier New', monospace;
  font-size: 1.8rem;
  font-weight: bold;
  color: var(--focus);
  letter-spacing: 2px;
}

.controls {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  justify-content: center;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 16px;
  border: 2px solid var(--accent);
  border-radius: 6px;
  background: var(--btn-bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  flex: 1 1 auto;
  min-width: 80px;
}

.btn:hover {
  background: var(--btn-hover);
}

.btn:active {
  background: var(--btn-active);
  transform: scale(0.97);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.clear {
  background: var(--accent);
  color: #fff;
}

.clear:hover {
  background: #c73550;
}

.clear:active {
  background: #a02a40;
}

.hint {
  margin-top: 16px;
  font-size: 0.85rem;
  color: var(--muted);
}

[hidden] {
  display: none !important;
}

@media (max-width: 400px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.2rem;
  }
  #timeDisplay, #priceDisplay {
    font-size: 1.5rem;
  }
  .btn {
    font-size: 0.95rem;
    padding: 10px 12px;
  }
}

(function () {
  'use strict';

  const MAX_MINUTES = 180;
  const RATE_PER_HOUR = 2.00;

  let paidMinutes = 0;

  const timeDisplay = document.getElementById('timeDisplay');
  const priceDisplay = document.getElementById('priceDisplay');
  const add15 = document.getElementById('add15');
  const add60 = document.getElementById('add60');
  const clearBtn = document.getElementById('clear');
  const canvas = document.getElementById('meterCanvas');
  const ctx = canvas.getContext('2d');

  function formatTime(minutes) {
    const h = Math.floor(minutes / 60);
    const m = minutes % 60;
    return h + ':' + String(m).padStart(2, '0');
  }

  function formatPrice(minutes) {
    const price = (minutes / 60) * RATE_PER_HOUR;
    return '$' + price.toFixed(2);
  }

  function render() {
    timeDisplay.textContent = formatTime(paidMinutes);
    priceDisplay.textContent = formatPrice(paidMinutes);
    drawMeter();
  }

  function addMinutes(mins) {
    paidMinutes = Math.min(paidMinutes + mins, MAX_MINUTES);
    render();
  }

  function clearMeter() {
    paidMinutes = 0;
    render();
  }

  function drawMeter() {
    const w = canvas.width;
    const h = canvas.height;
    ctx.clearRect(0, 0, w, h);

    // Pixel art parking meter
    const scale = 8;
    const cx = w / 2;

    // Post
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(cx - scale, 60, scale * 2, 50);

    // Meter head
    ctx.fillStyle = '#e94560';
    ctx.fillRect(cx - scale * 4, 10, scale * 8, scale * 6);

    // Screen
    ctx.fillStyle = '#0a0a1a';
    ctx.fillRect(cx - scale * 3, 18, scale * 6, scale * 3);

    // Screen content (time bar)
    const fillRatio = paidMinutes / MAX_MINUTES;
    ctx.fillStyle = '#f5c542';
    const barWidth = Math.floor(scale * 5 * fillRatio);
    if (barWidth > 0) {
      ctx.fillRect(cx - scale * 2.5, 22, barWidth, scale * 2);
    }

    // Coin slot
    ctx.fillStyle = '#a0a0b0';
    ctx.fillRect(cx - scale, 50, scale * 2, scale);

    // Base
    ctx.fillStyle = '#0f3460';
    ctx.fillRect(cx - scale * 2, 110, scale * 4, scale);
  }

  add15.addEventListener('click', function () {
    addMinutes(15);
  });

  add60.addEventListener('click', function () {
    addMinutes(60);
  });

  clearBtn.addEventListener('click', clearMeter);

  render();
})();
